class MagicalItem {
    constructor(name, powerLevel) {
        this.name = name;
        this.powerLevel = powerLevel;
    }

    getDescription() {
        return `This is a ${this.name} with a power level of ${this.powerLevel}.`;
    }
}

class EnchantedSword extends MagicalItem {
    constructor(name, powerLevel, material) {
        super(name, powerLevel);
        this.material = material;
    }

    swing() {
        return `The ${this.material} ${this.name} swings with a force of ${this.powerLevel}!`;
    }
}

// Test your code
const ancientBlade = new EnchantedSword("Ancient Blade", 85, "Mithril");
console.log(ancientBlade.getDescription());
console.log(ancientBlade.swing());

const healingPotion = new MagicalItem("Healing Potion", 20);
console.log(healingPotion.getDescription());

